+namespace sv_f8abd036fff348a896eb5f1d84f10de4.Services;
+
+/// <summary>
+/// Scoped service (per-circuit) that polls for low-stock alerts and
+/// notifies all subscribed components when new data arrives.
+/// </summary>
+public class InventoryAlertService : IDisposable
+{
+    private readonly WarehouseStateService _warehouseState;
+    private readonly Random _random = new();
+    private Timer? _timer;
+    private int _subscriberCount;
+    private int _currentAlertCount;
+
+    public int CurrentAlertCount => _currentAlertCount;
+
+    public event Action? OnAlertCountChanged;
+
+    public InventoryAlertService(WarehouseStateService warehouseState)
+    {
+        _warehouseState = warehouseState;
+        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
+    }
+
+    /// <summary>
+    /// Simulates a database query returning low-stock item count for a warehouse.
+    /// </summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        var count = _random.Next(0, 16);
+        return Task.FromResult(count);
+    }
+
+    /// <summary>
+    /// Starts polling if not already active. Uses reference counting so
+    /// multiple components can subscribe/unsubscribe independently.
+    /// </summary>
+    public void StartPolling()
+    {
+        _subscriberCount++;
+        if (_timer is null)
+        {
+            _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
+        }
+    }
+
+    /// <summary>
+    /// Decrements subscriber count and stops polling when no subscribers remain.
+    /// </summary>
+    public void StopPolling()
+    {
+        _subscriberCount = Math.Max(0, _subscriberCount - 1);
+        if (_subscriberCount == 0)
+        {
+            _timer?.Dispose();
+            _timer = null;
+        }
+    }
+
+    private async void PollCallback(object? state)
+    {
+        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
+        _currentAlertCount = count;
+        OnAlertCountChanged?.Invoke();
+    }
+
+    private async void HandleWarehouseChanged()
+    {
+        // Immediately refresh when warehouse changes
+        if (_timer is not null)
+        {
+            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
+            _currentAlertCount = count;
+            OnAlertCountChanged?.Invoke();
+        }
+    }
+
+    public void Dispose()
+    {
+        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
+        _timer?.Dispose();
+        _timer = null;
+    }
+}
