@using sv_f8abd036fff348a896eb5f1d84f10de4.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">
            @CurrentWarehouseName
            <span class="text-muted fs-6">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            <span class="badge @BadgeClass ms-2">@AlertService.CurrentAlertCount items</span>
        </h5>
        <p class="card-text text-muted">
            Polling every 10 seconds for items below minimum stock levels.
        </p>
        @if (AlertService.CurrentAlertCount > 5)
        {
            <div class="alert alert-danger mt-2" role="alert">
                ⚠️ High number of low-stock items detected! Consider reordering.
            </div>
        }
        else if (AlertService.CurrentAlertCount > 0)
        {
            <div class="alert alert-warning mt-2" role="alert">
                Some items are running low. Review inventory levels.
            </div>
        }
        else
        {
            <div class="alert alert-success mt-2" role="alert">
                ✅ All stock levels are healthy.
            </div>
        }
    </div>
</div>

@code {
    private string BadgeClass => AlertService.CurrentAlertCount > 5 ? "bg-danger" : "bg-warning text-dark";

    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? WarehouseState.CurrentWarehouseId;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleStateChanged;
        AlertService.StartPolling();
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleStateChanged;
        AlertService.StopPolling();
    }
}

